// Het ⌕ als uitgang naar een GENERIEKE RDF-verkenner.
//
// Herbouw van viewer-bevroren/assets/verken.js in de nieuwe laag. Dat bestand blijft in
// de bevroren viewer staan (het is UI: het maakt een <a> met de hand); wat hier
// meeverhuist is de PURE kant — welke knoop een adres heeft, welke query er
// meegaat en welke bronnen de client krijgt. Woord voor woord hetzelfde
// gedrag, want een ⌕-link uit de oude viewer moet in de nieuwe app dezelfde
// pagina openen; alleen de namen zijn Nederlands geworden.
//
// De client leest zijn staat uit de HASH van de URL (ldf-client-url-state in de
// meegeleverde bundel):
//     #datasources=<url>;<url>&query=<sparql>&executeOnLoad=true
// Elke hash-waarde wordt door de client in één keer gedecodeerd en pas daarna
// op [ ,;] gesplitst; per datasource dus encodeURIComponent en samenvoegen met
// ';'. Een datasource mag GETYPEERD zijn als "type@url" (de client splitst op
// de eerste '@'); zie verkenBronnen voor waarom het SPARQL-endpoint dat moet.
//
// DOM-vrij: dit bestand raakt `document` niet aan.
import { COMUNICA_BASE } from '../../model/default-corpus.js';
import { termVan } from '../../model/term.js';

/** Waar de meegeleverde client staat, gezien vanaf de pagina. Dit is de
 *  TERUGVAL; de deployment-configuratie (default-corpus.js) is leidend. */
export const COMUNICA_PAD = COMUNICA_BASE;

/** Wat er allemaal een IRI kan dragen: een string, een N3-term of een kale
 *  { id }-handle uit de worker. */
export type TermOfIri =
  | string
  | null
  | undefined
  | { termType?: string; value?: string; id?: string };

export interface VerkenBron { name?: string; url?: string; fromSparql?: boolean }

export interface VerkenStaat {
  sources?: readonly VerkenBron[];
  sparqlEndpoint?: string | null;
}

// --- IRI's ------------------------------------------------------------------

/** De IRI achter wat de weergave doorgeeft. Een BLANKE KNOOP levert null: die
 *  heeft geen adres buiten dit document en is dus in een generieke verkenner
 *  niet aan te wijzen — daar hoort dan ook geen ⌕ bij.
 *
 *  De vormherkenning (string, echte term, worker-handle) stond hier uitgeschreven
 *  en was decodeerplek 7 van de elf — met `asTerm` in `model/model-client.js` de
 *  enige andere in de INSTAPCHUNK. Zij komt nu uit `model/term.js`; wat hier
 *  overblijft is het OORDEEL dat deze module toevoegt: alleen een NamedNode
 *  heeft een adres, en alleen als hij als <IRI> in een query mag staan. */
export function iriOf(termOfIri: TermOfIri): string | null {
  const t = termVan(termOfIri) as { termType?: string; value?: string } | null;
  return t && t.termType === 'NamedNode' ? geldigeIri(t.value) : null;
}

// Alleen wat als <IRI> in een SPARQL-query mag staan (IRIREF-grammatica): een
// absolute IRI zonder de tekens die de haakjesvorm zouden breken.
function geldigeIri(s: string | undefined): string | null {
  const v = String(s || '');
  if (!/^[A-Za-z][A-Za-z0-9+.-]*:/.test(v)) return null;
  if (/[\s<>"{}|\\^`]/.test(v)) return null;
  return v;
}

// --- De query ---------------------------------------------------------------

/** EEN CONSTRUCT, GEEN DESCRIBE OF SELECT (uitgeprobeerd in de client zelf).
 *  DESCRIBE toont alleen wat de knoop zélf zegt en verzwijgt wie naar hem
 *  verwijst; een SELECT levert per triple een blok met ?variabele-labels en
 *  leest als een formulier. De CONSTRUCT hieronder geeft precies de twee
 *  richtingen die de weergave ook toont ("verwijst naar" / "verwezen vanuit"),
 *  en de client serialiseert het resultaat als Turtle met prefixen. */
export function knoopQuery(iri: string): string | null {
  const v = geldigeIri(iri);
  if (!v) return null;
  return 'CONSTRUCT {\n'
    + `  <${v}> ?uit ?object .\n`
    + `  ?subject ?in <${v}> .\n`
    + '}\nWHERE {\n'
    + `  { <${v}> ?uit ?object }\n`
    + '  UNION\n'
    + `  { ?subject ?in <${v}> }\n`
    + '}';
}

// --- De bronnen -------------------------------------------------------------

function absoluut(url: string | undefined, paginaUrl: string | null): string | null {
  const u = String(url || '');
  if (!u) return null;
  if (!paginaUrl) return u;
  try { return new URL(u, paginaUrl).href; } catch { return u; }
}

/** De datasources die de verkenner moet laden: in bestandsmodus de bron-URL's
 *  van deze pagina, absoluut gemaakt (de client draait op een ander pad en kan
 *  met "../data/…" niets), in endpoint-modus het SPARQL-endpoint. Staan ze
 *  allebei aan, dan gaan ze allebei mee. Pseudo-bronnen die uit het endpoint
 *  zelf komen (detail-CONSTRUCTs, knoop-CONSTRUCTs) hebben geen eigen URL en
 *  tellen niet mee.
 *
 *  HET ENDPOINT KRIJGT EEN TYPEPREFIX: `sparql@<url>`. De client leest een
 *  bronstring als "type@url" wanneer er een '@' vóór de URL staat, en slaat dan
 *  het SNIFFEN van het brontype over. Zonder die prefix haalt de engine de kale
 *  endpoint-URL eerst met een GET zonder query op om te zien wát het is; een
 *  Fuseki antwoordt daarop met 404 en de verkenner meldt "Metadata extraction …
 *  failed". Bestandsbronnen blijven kaal: daar is het sniffen juist correct.
 *  De prefix komt vóór de VOLLEDIGE absolute URL — de resolver ziet hem dus
 *  nooit (een 'sparql@http://…' zou hij als relatief pad opvatten). */
export function verkenBronnen(
  { sources = [], sparqlEndpoint = null }: VerkenStaat = {},
  paginaUrl: string | null = null,
): string[] {
  const uit: string[] = [];
  const voegToe = (u: string | undefined, type: string | null = null) => {
    const abs = absoluut(u, paginaUrl);
    if (!abs) return;
    const entry = type ? type + '@' + abs : abs;
    if (!uit.includes(entry)) uit.push(entry);
  };
  for (const s of sources || []) {
    if (!s || s.fromSparql || !s.url) continue;
    voegToe(s.url);
  }
  if (sparqlEndpoint) voegToe(sparqlEndpoint, 'sparql');
  return uit;
}

// --- De URL -----------------------------------------------------------------

// De client codeert hash-waarden met encodeURIComponent plus de haakjes (zijn
// eigen encodeURIComponentExtended); wij schrijven ze net zo, zodat een link
// die de gebruiker deelt er hetzelfde uitziet als een die de client zelf
// bijwerkt.
function codeer(s: string): string {
  return encodeURIComponent(String(s)).replace(/\(/g, '%28').replace(/\)/g, '%29');
}

export function comunicaUrl({
  base = COMUNICA_PAD, datasources = [], query = '', pageUrl = null,
}: {
  base?: string; datasources?: readonly string[]; query?: string; pageUrl?: string | null;
} = {}): string {
  const delen: string[] = [];
  if (datasources && datasources.length) {
    delen.push('datasources=' + datasources.map(codeer).join(';'));
  }
  if (query) {
    delen.push('query=' + codeer(query));
    // Meteen uitvoeren: de link is een antwoord, geen invuloefening. ALLEEN
    // met bronnen: zonder datasources zou de client op de eerste seconde een
    // foutbalk tonen. Dat gebeurt wanneer de pagina uit lokaal geopende
    // bestanden leest — die hebben geen URL die een andere pagina kan halen.
    if (datasources && datasources.length) delen.push('executeOnLoad=true');
  }
  const href = absoluut(base, pageUrl) || base;
  return delen.length ? href + '#' + delen.join('&') : href;
}

/** De volledige ⌕-bestemming voor één knoop. null = geen bestemming (blanke
 *  knoop of geen bruikbare IRI); de aanroeper laat het ⌕ dan weg. */
export function verkenHref(
  termOfIri: TermOfIri,
  staat: VerkenStaat = {},
  { base = COMUNICA_PAD, pageUrl = null }: { base?: string; pageUrl?: string | null } = {},
): string | null {
  const iri = iriOf(termOfIri);
  if (!iri) return null;
  return comunicaUrl({
    base,
    datasources: verkenBronnen(staat, pageUrl),
    query: knoopQuery(iri) || '',
    pageUrl,
  });
}
