// BEVINDING I4 — de verkenner-stand in de BROWSERGESCHIEDENIS.
//
// De bevroren viewer schrijft ?verken= bewust met history.pushState en luistert
// op popstate (viewer-bevroren/assets/doc.js: openVerken/showInDoc/applyVerkenFromUrl).
// Reden: document en verkenner zijn twee STANDEN van dezelfde pagina, en elke
// klik in de verkenner is een navigatiestap — terug en vooruit horen daar
// doorheen te lopen. De weergavestore van de nieuwe app schrijft daarentegen
// alles met replaceState, en met reden: een filterkeuze mag geen
// geschiedenisstap zijn, anders moet de lezer door zijn eigen filters heen
// terugklikken.
//
// Deze module verzoent die twee zonder de store-regel om te gooien:
//
//   1. history.pushState EERST — een nieuwe stap, met de nieuwe URL;
//   2. zetWeergave DAARNA — die schrijft de hele store met replaceState naar
//      diezelfde, zojuist gemaakte stap.
//
// Netto: precies één geschiedenisstap per verkennersprong, elke andere
// weergavekeuze blijft een replaceState, en de adresbalk blijft per constructie
// gelijk aan de store (naarUrl is totaal).
//
// De href van elke ⌕-link en elke verwijzingsrij komt uit dezelfde functie
// (verkenUrl), zodat middelklik, "openen in nieuw tabblad" en kopiëren gewoon
// werken — dat is de reden dat het een <a href> is en geen knop.
import { naarUrl, weergave, zetWeergave } from '../../stores/weergave.js';

/** De deelbare URL van de verkenner-stand op één knoop, resp. (met null) van de
 *  documentweergave. Alle overige parameters van deze pagina (?src=, ?policy=,
 *  ?lang=, filters) reizen mee: een gedeelde verkenner-link laadt dus dezelfde
 *  bronnen als de pagina waar hij vandaan komt. */
export function verkenUrl(iri: string | null): string {
  const basis = typeof location !== 'undefined'
    ? new URLSearchParams(location.search) : new URLSearchParams();
  const q = naarUrl({ ...weergave, verkenIri: iri }, basis).toString();
  if (q) return '?' + q;
  return typeof location !== 'undefined' ? location.pathname : '';
}

function duw(iri: string | null): void {
  if (typeof history === 'undefined' || !history.pushState) return;
  history.pushState({ verken: iri }, '', verkenUrl(iri));
}

/** Naar de verkenner, op één knoop: een nieuwe stap in de browsergeschiedenis. */
export function openVerken(iri: string): void {
  if (!iri) return;
  duw(iri);
  zetWeergave({ verkenIri: iri, stand: 'verken' });
  // BOVENAAN BEGINNEN. Een sprong is een nieuwe pagina-inhoud, geen scroll
  // binnen dezelfde; zonder dit opent een knoop die je onderaan een lange
  // verwijzingslijst aanklikte halverwege het scherm (gemeten op /brp-ap:
  // scrollY 1098 tegen 0 in de bevroren viewer). doc.js doet hetzelfde in
  // openVerken r.949 — en bewust NIET in showInDoc, want daar springt de
  // documentweergave zelf naar de knoop.
  if (typeof window !== 'undefined' && window.scrollTo) window.scrollTo(0, 0);
}

/** Terug naar het document. Ook dat is een geschiedenisstap: anders zou terug
 *  vanuit het document naar de verkenner springen die je zojuist verliet. */
export function sluitVerken(): void {
  duw(null);
  zetWeergave({ verkenIri: null, stand: 'doc' });
}

/** De stand die de URL beschrijft aanzetten. Aangeroepen bij browser-terug en
 *  -vooruit; raakt de geschiedenis dus NIET (geen pushState). Alleen ?verken=
 *  wordt gelezen — de overige weergavekeuzes staan al in de store en zijn per
 *  replaceState met deze geschiedenisstap meegeschreven. */
export function pasVerkenUitUrlToe(): void {
  const iri = typeof location !== 'undefined'
    ? new URLSearchParams(location.search).get('verken') : null;
  if ((iri || null) === weergave.verkenIri) return;
  zetWeergave({ verkenIri: iri || null, stand: iri ? 'verken' : 'doc' });
}

/** Koppel de popstate-luisteraar. Levert de ontkoppelaar terug (Solid:
 *  `onCleanup(koppelVerkenHistorie())`). */
export function koppelVerkenHistorie(): () => void {
  if (typeof window === 'undefined' || !window.addEventListener) return () => {};
  const luister = () => pasVerkenUitUrlToe();
  window.addEventListener('popstate', luister);
  return () => window.removeEventListener('popstate', luister);
}
